// Persistent relics: one loadout, 100 stored pieces; all transactions persist immediately.
const RELIC_CATEGORIES=[['journey','探索開始時',30],['opening','戦闘開始・終了時',28],['combat','戦闘中',15],['energy','エナジー最大値',7],['status','ステータス',12],['cards','カード効果',8]];
const RELIC_EFFECTS=[
{id:'start_cards',cat:'journey',name:'未知の契約',text:'探索開始時、ランダムな潜在カードを2枚取得。'},
...POTIONS.map(p=>({id:'start_'+p.id,cat:'journey',name:p.name+'の備え',text:'探索開始時、'+p.name+'を1個得る。',potion:p.id})),
{id:'opening_draw',cat:'opening',name:'先読み',text:'戦闘開始時、追加でカードを2枚引く。'},
{id:'opening_energy',cat:'opening',name:'初動の火',text:'戦闘開始時、エナジー+1。'},
{id:'victory_heal',cat:'opening',name:'勝利の余韻',text:'戦闘終了時、HPを4回復。'},
{id:'first_block',cat:'combat',name:'最初の盾',text:'戦闘で初めてカードから得るブロックを2倍にする。'},
{id:'zero_block',cat:'combat',name:'零の守り',text:'0コストのカードを使用するたび1ブロック。'},
{id:'four_blocks',cat:'combat',name:'防御の習熟',text:'戦闘中、ブロックを4回得るたび守護+1。'},
{id:'energy_hp',cat:'energy',name:'命を削る火',text:'エナジー最大値+1。最大HPが20%減少。'},
{id:'energy_potions',cat:'energy',name:'薬を拒む火',text:'エナジー最大値+1。消費アイテムを所持できない。'},
{id:'energy_epic',cat:'energy',name:'希少性を捨てる火',text:'エナジー最大値+1。ラン中、EPICカードが出現しない。'},
{id:'energy_draw',cat:'energy',name:'閉じた知識',text:'エナジー最大値+1。追加ドローができない。戦闘・ターン開始時の通常ドローのみ可能。'},
{id:'energy_rest',cat:'energy',name:'眠らない火',text:'エナジー最大値+1。休息マスでHPを回復できない。'},
{id:'energy_hand',cat:'energy',name:'細い契約',text:'エナジー最大値+1。戦闘・ターン開始時に引くカードが1枚減少。'},
{id:'early_strength',cat:'status',name:'先駆けの力',text:'3戦目まで、戦闘開始時に筋力+1。'},
{id:'elite_strength',cat:'status',name:'強敵の記憶',text:'強敵を倒すとラン中のスタック+1。戦闘開始時、その数だけ筋力を得る。'},
{id:'growing_strength',cat:'status',name:'戦いの呼び声',text:'3・6・9…ターン開始時、自身の筋力+2、生存している敵全体の筋力+1。'},
{id:'unknown_status',cat:'status',name:'未知の祝福',text:'不明マスでラン中のスタック+1。戦闘開始時、その数だけランダムな筋力・守護・プレート・再生を各+1。'},
{id:'card_maxhp',cat:'status',name:'契約の器',text:'探索中、カードをデッキに追加するたび最大HPと現在HP+1。'},
{id:'poison_boost',cat:'cards',name:'毒の代償',text:'毒の付与量+1。戦闘開始時、自身に毒5。'},
{id:'double_cards',cat:'cards',name:'倍加する契約',text:'ダメージ・ブロック以外のカード効果の数値が2倍。すべてのカードのコスト+1。'}
];
const RELIC_BY_ID=Object.fromEntries(RELIC_EFFECTS.map(e=>[e.id,e]));
S.relicVault??=[];S.relicPoints??=0;S.relicQueue??=[];S.relicSerial??=0;S.equippedRelicId??=null;
let relicSearch='',relicView='list',relicFavoriteOnly=false,relicConfirm=null,relicEffectFilter=[];
function relicEffect(id){return RELIC_BY_ID[id]}
function hasRelic(id,r=S.run){return !!r?.carriedRelic?.effects?.includes(id)}
function equippedRelic(){return S.relicVault.find(x=>x.id===S.equippedRelicId)||null}
function relicSummary(x){return x.effects.map(id=>relicEffect(id)?.text||'旧効果').join(' ／ ')}
function rollRelicEffect(exclude=[],other=[]){let options=RELIC_EFFECTS.filter(e=>!exclude.includes(e.id)&&!(e.cat==='energy'&&other.some(id=>relicEffect(id)?.cat==='energy')));let cats=RELIC_CATEGORIES.filter(([id])=>options.some(e=>e.cat===id)),total=cats.reduce((n,c)=>n+c[2],0),x=Math.random()*total,cat=cats.at(-1)?.[0];for(let c of cats){x-=c[2];if(x<0){cat=c[0];break}}return rand(options.filter(e=>e.cat===cat))?.id}
function newRelic(){let count=1,effects=[];if(Math.random()<.6){count++;if(Math.random()<.4)count++}for(let i=0;i<count;i++){let id=rollRelicEffect(effects,effects);if(id)effects.push(id)}let serial=++S.relicSerial;return {id:'relic-'+serial,name:rand(['灰燼の印','残火の護符','古王の欠片','黒曜の環','契約の紋章'])+' #'+serial,icon:rand(['◈','◇','✧','☽','♜']),effects,favorite:false}}
function relicEditable(){return !S.run&&!busy&&!S.relicReroll}
function equipRelic(id){if(!relicEditable())return;S.equippedRelicId=id===null?null:S.relicVault.some(x=>x.id===id)?id:S.equippedRelicId;save();render()}
function favoriteRelic(id){let x=S.relicVault.find(x=>x.id===id);if(!x)return;x.favorite=!x.favorite;render()}
function requestDismantle(id){if(!relicEditable())return;let ids=id?[id]:S.relicVault.filter(x=>!x.favorite).map(x=>x.id);ids=ids.filter(id=>S.relicVault.some(x=>x.id===id&&!x.favorite));if(!ids.length)return;relicConfirm=ids;render()}
function dismantleRelics(){if(!relicEditable()||!relicConfirm)return;let ids=relicConfirm.filter(id=>S.relicVault.some(x=>x.id===id&&!x.favorite));S.relicVault=S.relicVault.filter(x=>!ids.includes(x.id));if(ids.includes(S.equippedRelicId))S.equippedRelicId=null;S.relicPoints+=ids.length;relicConfirm=null;render();toast(ids.length+'個を分解しました')}
function beginRelicReroll(id,slot){if(!relicEditable()||S.relicPoints<1)return;let x=S.relicVault.find(x=>x.id===id);if(!x||!x.effects[slot]||(x.rerolls||0)>=5)return;let other=x.effects.filter((_,i)=>i!==slot),candidate=rollRelicEffect(x.effects,other);if(!candidate)return;S.relicPoints--;x.rerolls=(x.rerolls||0)+1;S.relicReroll={id,slot,old:x.effects[slot],candidate};render()}
function resolveRelicReroll(accept){let p=S.relicReroll;if(!p||S.run)return;let x=S.relicVault.find(x=>x.id===p.id);if(accept&&x&&x.effects[p.slot]===p.old)x.effects[p.slot]=p.candidate;S.relicReroll=null;render()}
function keepAppraisedRelic(){if(S.run||!S.relicQueue.length||S.relicVault.length>=100)return;S.relicVault.push(S.relicQueue.shift());render()}
function dismantleAppraisedRelic(){if(S.run||!S.relicQueue.length)return;S.relicQueue.shift();S.relicPoints++;render()}
function relicEffectsHTML(x,reroll=false){return `<ul class="relic-effects">${x.effects.map((id,i)=>{let e=relicEffect(id);return `<li><strong><span class="relic-effect-icon" aria-hidden="true">${relicEffectIcon(e)}</span> ${e.name}</strong><p>${relicEffectText(e)}</p>${reroll?`<button onclick="beginRelicReroll('${x.id}',${i})" ${!relicEditable()||S.relicPoints<1||(x.rerolls||0)>=5?'disabled':''}>この効果を再抽選 · 1pt</button>`:''}</li>`}).join('')}</ul>`}
function relicPanel(x,inventory=false){return `<article class="vault-relic ${x.id===S.equippedRelicId?'equipped':''}"><span class="relic-reroll-count" title="再抽選を実行した回数">再抽選可能回数 <b>${x.rerolls||0}</b>/5</span><div class="vault-title"><span class="vault-icon">${x.icon}</span><div><h3>${x.name}</h3><small>${x.effects.length}効果${x.id===S.equippedRelicId?' ／ 装備中':''}</small></div>${inventory?`<button class="favorite" onclick="favoriteRelic('${x.id}')" aria-label="お気に入り切替">${x.favorite?'★':'☆'}</button>`:''}</div>${inventory&&relicView==='icons'?`<div class="relic-skill-names">${x.effects.map(id=>`<span>${relicEffectIcon(relicEffect(id))} ${relicEffect(id).name}</span>`).join('')}</div>`:''}${inventory&&relicView==='icons'?'<button class="relic-expand" onclick="this.closest(\'article\').classList.toggle(\'expanded\')">効果を表示</button>':''}${relicEffectsHTML(x,inventory)}${inventory?`<div class="toolbar"><button onclick="equipRelic('${x.id}')" ${!relicEditable()||x.id===S.equippedRelicId?'disabled':''}>持ち込む</button><button onclick="requestDismantle('${x.id}')" ${!relicEditable()||x.favorite?'disabled':''}>分解 · +1pt</button></div>`:''}</article>`}
function relicsPage(){let equipped=S.run?S.run.carriedRelic:equippedRelic(),q=relicSearch.toLowerCase(),list=S.relicVault.filter(x=>(!relicFavoriteOnly||x.favorite)&&relicEffectFilter.every(id=>x.effects.includes(id))&&(x.name+' '+relicSummary(x)+' '+x.effects.map(id=>relicEffect(id).name).join(' ')).toLowerCase().includes(q));return `<div class="eyebrow">RELIC ATELIER</div><h2>遺物の工房</h2><p>持ち込める遺物は1個。遺物は周回をまたいで保管できます。デメリット効果を優先して適用します。</p><div class="relic-wallet"><b>✧ 遺物ポイント ${S.relicPoints}</b><span>保管 ${S.relicVault.length} / 100</span>${S.relicQueue.length?`<button class="primary" onclick="go('appraisal')">未鑑定品を確認 · ${S.relicQueue.length}</button>`:''}</div><h3>持ち込む遺物 ${S.run?'（ラン中は変更不可）':''}</h3>${equipped?relicPanel(equipped):'<div class="tile">遺物なし。強敵・ボスを討伐して未鑑定品を持ち帰りましょう。</div>'}${equipped&&!S.run?'<button onclick="equipRelic(null)" '+(!relicEditable()?'disabled':'')+'>持ち込みを解除</button>':''}<div class="section-head"><h3>保管庫</h3><button onclick="requestDismantle(null)" ${!relicEditable()?'disabled':''}>お気に入り以外を一括分解</button></div><div class="toolbar"><input id="relic-search" type="search" placeholder="遺物名・効果で検索" aria-label="遺物の検索"><details class="relic-effect-filter"><summary>遺物効果で絞り込み ${relicEffectFilter.length?'（'+relicEffectFilter.length+'件）':''}</summary><div>${RELIC_EFFECTS.map(e=>`<label><input type="checkbox" ${relicEffectFilter.includes(e.id)?'checked':''} onchange="toggleRelicEffectFilter('${e.id}',this.checked)">${relicEffectIcon(e)} ${e.name}</label>`).join('')}</div></details><button onclick="resetRelicSearch()">検索をリセット</button><button onclick="relicFavoriteOnly=!relicFavoriteOnly;render()">${relicFavoriteOnly?'★ お気に入りのみ':'☆ すべて'}</button><button onclick="relicView=relicView==='list'?'icons':'list';render()">${relicView==='list'?'アイコン表示へ':'効果一覧表示へ'}</button></div><div class="relic-vault ${relicView}">${list.map(x=>relicPanel(x,true)).join('')||'<p class="muted">該当する遺物はありません。</p>'}</div><details class="relic-rules"><summary>鑑定・再抽選のルール</summary><p>効果は1個目100%、2個目60%、3個目40%の順に抽選し、外れた時点で終了。同じ効果は重複せず、エナジー最大値の効果は1個まで。</p><p>カテゴリを抽選してから、その中の効果を等確率で抽選。${RELIC_CATEGORIES.map(c=>c[1]+c[2]+'%').join(' ／ ')}。除外後は残ったカテゴリの比率で再計算します。</p><p>再抽選は遺物1個につき最大5回、1回1pt。現在の効果と他枠の効果、重複するエナジーカテゴリを除外。不採用でもポイントは戻りません。</p><p>戦闘報酬の未鑑定品はクリアまでに2〜3個（各50%）。強敵で1個ずつ獲得し、ボスで残りを獲得。宝箱から別枠で1〜2個（各50%）を獲得し、合計3〜5個。敗北時は獲得済み分を持ち帰り、リタイア時は破棄します。</p></details>`}
function appraisalPage(){let x=S.relicQueue[0];return `<div class="eyebrow">RELIC APPRAISAL</div><h2>持ち帰った遺物の鑑定</h2><p>残り ${S.relicQueue.length}個 ／ 保管 ${S.relicVault.length} / 100 ／ 遺物ポイント ${S.relicPoints}</p>${x?`${relicPanel(x)}<div class="toolbar"><button class="primary" onclick="keepAppraisedRelic()" ${S.relicVault.length>=100?'disabled':''}>保管する</button><button onclick="dismantleAppraisedRelic()">分解する · +1pt</button><button onclick="go('relics')">保管庫を整理</button></div>${S.relicVault.length>=100?'<p>保管庫が満杯です。分解するか、保管庫を整理してください。</p>':''}`:'<div class="tile"><h3>鑑定が完了しました</h3><button class="primary" onclick="go(\'relics\')">遺物を選ぶ →</button> <button onclick="go(\'home\')">拠点へ</button></div>'}`}
function relicDialog(){let p=S.relicReroll;if(p)return `<div class="relic-modal"><section role="dialog" aria-modal="true"><h2>再抽選の結果</h2><p>1pt消費済み。不採用でも返還されません。</p><div class="reroll-options"><article><h3>現在の効果</h3><p>${relicEffect(p.old).text}</p></article><article><h3>新しい候補</h3><p>${relicEffect(p.candidate).text}</p></article></div><div class="toolbar"><button class="primary" onclick="resolveRelicReroll(true)">新しい効果を採用</button><button onclick="resolveRelicReroll(false)">元の効果を維持</button></div></section></div>`;if(relicConfirm)return `<div class="relic-modal"><section role="dialog" aria-modal="true"><h2>${relicConfirm.length}個を分解しますか？</h2><p>お気に入りは除外しています。${relicConfirm.includes(S.equippedRelicId)?'持ち込み中の遺物も含まれ、持ち込みが解除されます。':''}分解すると元に戻せません。</p><p>遺物ポイント +${relicConfirm.length}</p><div class="toolbar"><button onclick="relicConfirm=null;render()">キャンセル</button><button class="primary" onclick="dismantleRelics()">分解する</button></div></section></div>`;return ''}
// Runtime modifiers are a snapshot of the single carried relic.
allowedRunCard=function(c,r=S.run){return c.runOnly&&!c.retired&&!(hasRelic('energy_epic',r)&&c.rarity==='epic')};
addRunCard=function(r,id){let c=C[id];if(!c||!allowedRunCard(c,r)||r.deck.filter(x=>x===id).length>=3)return false;r.deck.push(id);if(hasRelic('card_maxhp',r)){r.max++;healHP(r,1)}return true};
const startRelicsBase=start;start=function(){if(S.run)return;if(S.relicQueue.length)return toast('先に持ち帰った遺物を鑑定してください');if(S.relicReroll)return toast('再抽選の結果を確定してください');let x=equippedRelic();x=x?JSON.parse(JSON.stringify(x)):null;startRelicsBase();let r=S.run;if(!r)return;r.carriedRelic=x?JSON.parse(JSON.stringify(x)):null;r.relics=x?[{...r.carriedRelic,type:'permanent',desc:relicSummary(x)}]:[];r.battleCount=0;r.eliteStacks=0;r.unknownStacks=0;r.unidentifiedRelics=0;let n=Math.random();r.relicTarget=n<.5?2:3;r.energyMax=hasAnyEnergy(r)?4:3;r.potions=[];if(hasRelic('energy_hp',r)){r.max=Math.floor(r.max*.8);r.hp=r.max}if(!hasRelic('energy_potions',r))for(let id of x?.effects||[]){let p=relicEffect(id)?.potion;if(p&&r.potions.length<2)r.potions.push(p)}if(hasRelic('start_cards',r))for(let i=0;i<2;i++){let pool=C.filter(c=>allowedRunCard(c,r)&&runCopies(r,c.id)<3);if(pool.length)addRunCard(r,rand(pool).id)}render()};
function hasAnyEnergy(r){return r.carriedRelic?.effects.some(id=>relicEffect(id)?.cat==='energy')||false}
const drawRelicsBase=draw;draw=function(n,baseline=false){let r=S.run;if(!r)return;if(!baseline&&hasRelic('energy_draw',r))return;if(baseline&&hasRelic('energy_hand',r))n=Math.max(0,n-1);return drawRelicsBase(n)};
const chooseRelicsBase=choose;choose=function(type){let r=S.run;if(!r)return;if(type==='unknown'&&hasRelic('unknown_status',r))r.unknownStacks=(r.unknownStacks||0)+1;if(type==='rest'&&hasRelic('energy_rest',r)){r.kind='rest';r.mode=page='rest';render();return}let combat=['fight','elite','boss'].includes(type);if(combat){r.battleCount=(r.battleCount||0)+1;r.firstCardBlock=false;r.blockGainCount=0;r.poison=0;r.battleRelicGranted=false;r.heartbeatRefund=1;r.potionTarget=null}chooseRelicsBase(type);if(combat&&r.mode==='battle'){r.energyMax=hasAnyEnergy(r)?4:3;r.energy=r.energyMax+(hasRelic('opening_energy',r)?1:0);if(hasRelic('early_strength',r)&&r.battleCount<=3)r.str++;if(hasRelic('elite_strength',r))r.str+=r.eliteStacks||0;if(hasRelic('unknown_status',r))for(let i=0;i<(r.unknownStacks||0);i++){let k=rand(['str','agility','plate','regen']);r[k]=(r[k]||0)+1}if(hasRelic('poison_boost',r))r.poison=5;if(hasRelic('opening_draw',r))draw(2);render()}};
const restRelicsBase=rest;rest=function(){if(hasRelic('energy_rest'))return `<div class="reward"><div class="eyebrow">REST</div><h1>眠らない火。</h1><p>遺物の代償により、この休息ではHPを回復できません。</p><button class="primary" onclick="next()">探索を続ける →</button></div>`;return restRelicsBase()};
const gainBlockRelicsBase=gainBlock;gainBlock=function(r,n,source='card'){let before=r.block;if(source==='card'&&hasRelic('first_block',r)&&!r.firstCardBlock){n+=10;r.firstCardBlock=true}gainBlockRelicsBase(r,n,source);if(r.block>before&&hasRelic('four_blocks',r)){r.blockGainCount=(r.blockGainCount||0)+1;if(r.blockGainCount%4===0)r.agility=(r.agility||0)+1}};
function onCardResolved(r,c){if(c.cost===0&&hasRelic('zero_block',r))gainBlock(r,1,'relic')}
const applyBuffsRelicsBase=applyTurnStartBuffs;applyTurnStartBuffs=function(r){if(r.poison>0){r.hp=Math.max(0,r.hp-r.poison);r.poison--;if(r.hp<=0)return}triggerBattleCall(r);applyBuffsRelicsBase(r)};
const forecastRelicsBase=forecastDamage;forecastDamage=r=>forecastRelicsBase(r)+(r.poison||0)+(r.passion||0);
// All card numerical effect values are doubled; flags and trigger conditions retain their meaning.
combatCard=function(id){let c=C[id],r=S.run;if(!c||!r)return c;let fx={...c.fx},desc=c.desc,cost=c.cost;if(hasRelic('double_cards',r)){let numbers=['selfDamage','strengthBlock','d','h','b','p','heal','s','energy','draw','discard','recover','sacrifice','agility','plate','regen','nextBlock','blockBonus','passion','exScale','blockScale','strScale','exactBlock','equalPoison','totalPoison','strBonus','engine','chooseExhaust','lowEnergy'];for(let k of numbers)if(typeof fx[k]==='number')fx[k]*=2;if(fx.doubleStr)fx.strMultiplier=4;if(fx.poisonDouble)fx.poisonTicks=4;if(fx.heartbeat)fx.heartbeatRefund=2;if(fx.discardBreak)fx.discardCount=2;if(fx.exhaustBlock)fx.exhaustBlock=2;desc=desc.replace(/-?\d+(?:\.\d+)?/g,n=>String(Number(n)*2));if(c.fx.lowEnergy)desc=desc.replace('半分','半分');cost++;desc+=' 【遺物：効果値2倍・コスト+1】'}if(fx.p&&hasRelic('poison_boost',r)){fx.p++;desc=desc.replace(/毒を\d+付与/,`毒を${fx.p}付与`)}return {...c,cost,fx,desc}};
// Preview effective amounts without scaling twice or mutating shared card definitions.
const descRelicsBase=combatDesc;combatDesc=function(c,r){let d=descRelicsBase(c,r);if(c.fx.b){let first=hasRelic('first_block',r)&&!r.firstCardBlock?10:0;d=d.replace(/<strong class="boost">\d+ブロック<\/strong>/,`<strong class="boost">${blockValue(r,c.fx.b+first)}ブロック</strong>`)}if(c.fx.strengthBlock)d=`筋力スタック×${c.fx.strengthBlock}のブロック。現在 ${blockValue(r,r.str*c.fx.strengthBlock+(hasRelic('first_block',r)&&!r.firstCardBlock?10:0))}ブロック。`;if(c.fx.exScale)d=`${previewDamage(c,r,r.enemies[target])}ダメージ。除外済み1枚につき+${c.fx.exScale}。${c.fx.ex?'除外。':''}`;if(c.fx.blockScale)d=`${previewDamage(c,r,r.enemies[target])}ダメージ（基礎${c.fx.d}＋筋力＋ブロック×${c.fx.blockScale}、端数切り捨て）。${c.fx.b?blockValue(r,c.fx.b)+'ブロック。':''}`;if(c.fx.strBonus)d=`筋力+${c.fx.s}。既に筋力4以上なら、さらに+${c.fx.strBonus}。除外。`;if(c.fx.poisonDouble)d=`この戦闘中、敵の毒が${c.fx.poisonTicks||2}回発動。各発動で毒を1消費。除外。`;if(c.fx.doubleStr)d=`現在の筋力を${c.fx.strMultiplier||2}倍にする。除外。`;if(c.fx.lowEnergy)d=`HPが半分以下ならエナジー+${c.fx.lowEnergy}。除外。`;if(c.fx.exhaustBlock)d=`除外済みカード2枚につき${c.fx.exhaustBlock}ブロック。現在 ${blockValue(r,Math.floor(exhaustedCount(r)/2)*c.fx.exhaustBlock+(hasRelic('first_block',r)&&!r.firstCardBlock?10:0))}ブロック。除外。`;if(c.fx.heartbeat)d=`この戦闘中、エナジーを4消費するたび${c.fx.heartbeatRefund||1}回復。除外。`;return d};
// Suppression applies to every run acquisition source, including generated cards and the chest.
const epicRateRelicsBase=currentEpicRate;currentEpicRate=r=>hasRelic('energy_epic',r)?0:epicRateRelicsBase(r);
const sampleRelicsBase=sampleRunCards;sampleRunCards=rate=>sampleRelicsBase(hasRelic('energy_epic')?0:rate);
const canPotionRelicsBase=canUsePotion;canUsePotion=(p,allowTarget=false)=>!hasRelic('energy_potions')&&canPotionRelicsBase(p,allowTarget);
const buyPotionRelicsBase=buyShopPotion;buyShopPotion=function(i){if(hasRelic('energy_potions'))return toast('遺物の代償により消費アイテムを所持できません');buyPotionRelicsBase(i)};
const shopRelicsBase=buildShop;buildShop=function(r){let s=shopRelicsBase(r);if(hasRelic('energy_potions',r))s.potions=[];return s};
const shopHTMLRelicsBase=shopHTML;shopHTML=function(){return shopRelicsBaseHTML()+ (hasRelic('energy_epic')?'<p>遺物の代償によりEPICカードは出現しません。</p>':'')+(hasRelic('energy_potions')?'<p>遺物の代償により消費アイテムを購入できません。</p>':'')};
const shopRelicsBaseHTML=shopHTMLRelicsBase;
const chestRelicsBase=chestHTML;chestHTML=function(){let html=chestRelicsBase();if(hasRelic('energy_epic'))html=html.replace('潜在EPICカード1枚と、50金が入っています。','遺物の代償でEPICカードは出現しません。50金を獲得できます。').replace('すべてのEPICカードが3枚に達しているため、カードは取得できません。','この宝箱ではカードを取得できません。');return html};
// Loot is unidentified until return and never adds more carried relics during a run.
function addUnidentified(r,n){let room=Math.max(0,(r.relicTarget||3)-(r.unidentifiedRelics||0)),amount=Math.min(room,n);r.unidentifiedRelics=(r.unidentifiedRelics||0)+amount;r.lastRelicDrop=amount;return amount}
relic=function(){let r=S.run;addUnidentified(r,1);r.lastRelic={name:'未鑑定の遺物',icon:'?',type:'sealed',desc:'帰還後に鑑定。ラン中は効果を発揮しません。'}};
const victoryRelicsBase=victory;victory=function(){let r=S.run;if(!r||r.mode!=='battle'||r.battleRelicGranted)return;r.battleRelicGranted=true;if(hasRelic('victory_heal',r))healHP(r,4);if(r.kind==='elite'&&hasRelic('elite_strength',r))r.eliteStacks=(r.eliteStacks||0)+1;if(r.kind==='boss')addUnidentified(r,(r.relicTarget||3)-(r.unidentifiedRelics||0));victoryRelicsBase()};
const finishRelicsBase=finish;finish=function(win,ret=false){let r=S.run;if(!r)return;let amount=ret?0:r.unidentifiedRelics||0;for(let i=0;i<amount;i++)S.relicQueue.push(newRelic());finishRelicsBase(win,ret);if(S.history?.[0])S.history[0].unidentifiedRelics=amount;if(S.relicQueue.length){page='appraisal';render()}else save()};
const rewardRelicsBase=reward;reward=function(){let html=rewardRelicsBase().replace(/<p>COMMONで[\s\S]*?<\/p>/,'<p>今回のランのみ有効で、次の戦闘から山札に加わります。</p>').replace(/<p class="pity-status">[\s\S]*?<\/p>/,'');if(S.run?.kind==='elite')html+=`<p>未鑑定の遺物 ${S.run.lastRelicDrop||0}個を確保。ラン合計 ${S.run.unidentifiedRelics||0}個。帰還後に鑑定します。</p>`;if(hasRelic('energy_epic'))html+='<p>遺物の代償：EPICカードは出現しません。</p>';return html};
const relicIconLegacy=relicIcon;relicIcon=x=>x.icon||relicIconLegacy(x);
const battleRelicsBase=battle;battle=function(){let r=S.run,html=battleRelicsBase();html=html.replace('<small>/ 3</small>',`<small>/ ${r.energyMax||3}</small>`);if(r.poison>0)html=html.replace('<div class="player-status">',`<div class="player-status"><span class="status-help">毒 ${r.poison}<aside class="tooltip">次のターン開始時にブロックを無視してHPが${r.poison}減少し、毒が1減少。</aside></span>`);if(hasRelic('four_blocks',r))html=html.replace('<div class="player-status">',`<div class="player-status"><span class="status-help">防御の習熟 ${r.blockGainCount%4||0}/4</span>`);if(r.heartbeatRefund===2)html=html.replace('4消費するたびエナジー+1','4消費するたびエナジー+2');return html};
// Make relic effects inspectable in the codex, replacing the retired fixed-item list.
const bookRelicsBase=book;book=function(){if(bookType!=='relics')return bookRelicsBase();return `<div class="eyebrow">RELIC CODEX</div><h2>遺物の効果図鑑</h2><div class="toolbar"><button onclick="bookType='base';render()">基礎カード</button><button onclick="bookType='run';render()">潜在カード</button><button class="primary">遺物</button></div><p>1個に最大3効果。抽選はカテゴリ→効果の順。同じ効果は重複せず、エナジー最大値カテゴリは1個まで。</p>${RELIC_CATEGORIES.map(([cat,name,weight])=>`<h3>${name}</h3><div class="tiles">${RELIC_EFFECTS.filter(e=>e.cat===cat).map(e=>`<article class="tile"><h3>${relicEffectIcon(e)} ${e.name}</h3><p>${relicEffectText(e)}</p></article>`).join('')}</div>`).join('')}`};
const homeRelicsBase=home;home=function(){return homeRelicsBase()+`<section class="tile exchange-home"><h3>遺物の工房</h3><p>保管 ${S.relicVault.length}/100個 ／ 遺物ポイント ${S.relicPoints} ／ 鑑定待ち ${S.relicQueue.length}個</p><button onclick="go('relics')">遺物を管理 →</button>${S.relicQueue.length?'<button class="primary" onclick="go(\'appraisal\')">鑑定する</button>':''}</section>`};
const renderRelicsBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderRelicsBase();$('nav').innerHTML+=`<button class="${page==='relics'||page==='appraisal'?'active':''}" onclick="go('relics')">遺物${S.relicQueue.length?' · '+S.relicQueue.length:''}</button>`;if(page==='relics')$('app').innerHTML=relicsPage();if(page==='appraisal')$('app').innerHTML=appraisalPage();let x=S.run?.carriedRelic;if(x&&page!=='relics'&&page!=='appraisal')$('app').insertAdjacentHTML('afterbegin',`<div class="carried-relic"><span class="vault-icon">${x.icon}</span><div><strong>${x.name}</strong>${x.effects.map(id=>`<p>${relicEffect(id).text}</p>`).join('')}</div></div>`);if(page==='relics'){let input=$('relic-search');if(input){input.value=relicSearch;input.oninput=()=>{let start=input.selectionStart;relicSearch=input.value;render();let fresh=$('relic-search');fresh?.focus();fresh?.setSelectionRange(start,start)}}}let dialog=relicDialog();if(dialog&&!S.run)$('app').insertAdjacentHTML('beforeend',dialog);save()};
// Legacy in-progress runs keep their existing fixed relics until they return.
if(S.run){S.run.relicTarget=Math.min(3,S.run.relicTarget||3);S.run.unidentifiedRelics=Math.min(3+(S.run.chestRelics||0),S.run.unidentifiedRelics||0);S.run.unidentifiedRelics??=0;S.run.battleCount??=1;S.run.energyMax??=3}
if(!S.run&&S.relicQueue.length)page='appraisal';

